Synchronous - Asynchronous I-O.ejemplo:
// Linux io_uring: envío asíncrono (Proactor) sin bloquear en la copia
struct io_uring_sqe *sqe = io_uring_get_sqe(&ring);
io_uring_prep_read(sqe, sockfd, buf, sizeof(buf), 0);
io_uring_submit(&ring);
// El hilo continúa haciendo trabajo útil hasta recoger la CQE
struct io_uring_cqe *cqe;
io_uring_wait_cqe(&ring, &cqe);
// cqe->res contiene los bytes ya copiados en buf
io_uring_cqe_seen(&ring, cqe);

select - poll - epoll - kqueue - io_urin.ejemplo:
// Bucle mínimo con epoll en Linux (notificación O(1) de sockets listos)
int epfd = epoll_create1(0);
struct epoll_event ev = { .events = EPOLLIN, .data.fd = listen_fd };
epoll_ctl(epfd, EPOLL_CTL_ADD, listen_fd, &ev);
struct epoll_event events[64];
int n = epoll_wait(epfd, events, 64, -1); // Solo retorna los FDs activos

sync vs async I-O.ejemplo:
// Patrón seguro de guardado atómico en almacenamiento: escribir, fsync y rename
int fd = open("config.tmp", O_WRONLY | O_CREAT | O_TRUNC, 0644);
write(fd, data, len);
fsync(fd);      // Garantiza datos en disco antes de reemplazar el archivo
close(fd);
rename("config.tmp", "config.json");
